int link(const char *oldpath, const char *newpath);

// Creates hard link 'newpath' to 'oldpath'
if (link("/path/to/file", "new_hardlink") == -1) {
    // Check errno for EPERM (cross-device) or ENOENT
    return;
}

// linkat() variant: uses directory file descriptors
// flags: 0 or AT_SYMLINK_FOLLOW
int linkat(int olddirfd, const char *oldpath,
           int newdirfd, const char *newpath, int flags);

// Link file 'a' in dir FD 3 to 'b' in current dir (AT_FDCWD)
linkat(3, "a", AT_FDCWD, "b", 0);
